package android.os; import java.util.concurrent.ConcurrentLinkedQueue; public class Handler { private static final ConcurrentLinkedQueue<Runnable> Q=new ConcurrentLinkedQueue<>(); public Handler(Looper l){} public boolean post(Runnable r){Q.add(r);return true;} public void removeCallbacksAndMessages(Object o){Q.clear();} public static void drain(){Runnable r;while((r=Q.poll())!=null)r.run();} }
